from __future__ import annotations

from decimal import Decimal, InvalidOperation
from typing import Any


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric_value(value: Any) -> Decimal:
    if isinstance(value, str):
        text = value.strip()
        if text == "":
            return Decimal(0)
    else:
        text = str(value)

    try:
        return Decimal(text)
    except (InvalidOperation, ValueError):
        return Decimal("NaN")


def _lookup_role(user_id: str, users: list[dict]) -> Any:
    for user in users:
        if user.get("DEL_FLG", "") == "Y":
            continue
        if user.get("USR_ID", "") == user_id:
            return user.get("ROLE_ID", "")
    return ""


def set_discount(
    order: dict,
    pct: Any,
    user_id: str,
    users: list[dict],
) -> dict:
    numeric_pct = _numeric_value(pct)

    # ORD-001: evaluated first in legacy rule-file order.
    if not numeric_pct.is_finite() or not (
        Decimal(0) <= numeric_pct <= Decimal(100)
    ):
        raise BusinessRuleViolation("E5001", "Discount out of range")

    # ORD-002: LOOKUP returns the first live matching user's role.
    if numeric_pct > Decimal(20):
        role_id = _lookup_role(user_id, users)
        if role_id not in ("MGR", "ADMIN"):
            raise BusinessRuleViolation(
                "E5002",
                "Discount over 20 percent requires manager role",
            )

    updated_order = order.copy()
    updated_order["DISC_PCT"] = pct
    return updated_order
